INSERT INTO public.exam_questions (subject, grade, topic, difficulty, question_type, question_text, options, answer, explanation)
VALUES
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/1] การอ่านและการเขียนตัวเลขฮินดูอารบิก ตัวเลขไทย และตัวหนังสือ', 'easy', 'mcq', 'ตัวเลข "๔๘๕,๒๐๙" เขียนเป็นตัวหนังสือได้อย่างไร?', '["สี่แสนแปดหมื่นห้าพันสองร้อยเก้า","สี่หมื่นแปดพันห้าร้อยยี่สิบเก้า","สี่แสนแปดพันห้าร้อยยี่สิบเก้า","สี่แสนแปดหมื่นห้าพันยี่สิบเก้า"]'::jsonb, 0, '4 ในหลักแสน, 8 ในหลักหมื่น, 5 ในหลักพัน, 2 ในหลักร้อย, 0 ในหลักสิบ, 9 ในหลักหน่วย อ่านว่า สี่แสนแปดหมื่นห้าพันสองร้อยเก้า'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/1] ค่าประจำหลักและค่าของเลขโดด', 'easy', 'mcq', 'ในจำนวน 3,745,820 เลขโดด 4 อยู่ในหลักใด และมีค่าเท่าใด?', '["หลักแสน มีค่า 400,000","หลักหมื่น มีค่า 40,000","หลักพัน มีค่า 4,000","หลักร้อย มีค่า 400"]'::jsonb, 1, '3 (ล้าน), 7 (แสน), 4 (หมื่น) ดังนั้นเลข 4 อยู่ในหลักหมื่น มีค่าเท่ากับ 40,000'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/1] การเขียนในรูปกระจาย', 'easy', 'mcq', 'ข้อใดเป็นการเขียน 609,450 ในรูปกระจายที่ถูกต้อง?', '["600,000 + 9,000 + 400 + 50","60,000 + 9,000 + 400 + 5","600,000 + 90,000 + 400 + 50","6,000,000 + 9,000 + 450"]'::jsonb, 0, '609,450 = 600,000 + 0 + 9,000 + 400 + 50 + 0 ซึ่งเขียนแบบย่อคือ 600,000 + 9,000 + 400 + 50'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การเปรียบเทียบและเรียงลำดับจำนวน', 'medium', 'mcq', 'ข้อใดเรียงลำดับจำนวนจาก "มากไปน้อย" ได้ถูกต้อง?', '["785,100  792,400  810,000","950,210  948,990  948,750","523,000  532,000  519,000","405,600  406,500  404,900"]'::jsonb, 1, '950,210 > 948,990 > 948,750 เรียงลำดับจากค่ามากที่สุดไปหาค่าน้อยที่สุดถูกต้อง'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มสิบ', 'easy', 'mcq', 'ค่าประมาณเป็นจำนวนเต็มสิบของ 4,876 คือเท่าใด?', '["4,870","4,880","4,900","5,000"]'::jsonb, 1, 'พิจารณาหลักหน่วยคือ 6 (มากกว่าหรือเท่ากับ 5) จึงปัดขึ้นจาก 70 เป็น 80 ได้ 4,880'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มร้อยและเต็มพัน', 'medium', 'mcq', 'ค่าประมาณเป็นจำนวนเต็มร้อยของ 52,438 คือจำนวนใด?', '["52,400","52,500","52,000","53,000"]'::jsonb, 0, 'พิจารณาหลักสิบคือ 3 (น้อยกว่า 5) จึงปัดลง ได้ค่าประมาณเป็นจำนวนเต็มร้อยคือ 52,400'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มหมื่น', 'medium', 'mcq', 'ค่าประมาณเป็นจำนวนเต็มหมื่นของ 768,490 คือข้อใด?', '["760,000","770,000","800,000","768,000"]'::jsonb, 1, 'พิจารณาหลักพันคือ 8 (มากกว่าหรือเท่ากับ 5) ปัดขึ้นในหลักหมื่นจาก 60,000 เป็น 70,000 ได้ 770,000'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การหาค่าประมาณเป็นจำนวนเต็มแสน', 'medium', 'mcq', 'จำนวนในข้อใดมีค่าประมาณเป็นจำนวนเต็มแสนเท่ากับ 500,000?', '["429,999","551,000","478,500","580,200"]'::jsonb, 2, '478,500 พิจารณาหลักหมื่นคือ 7 (ปัดขึ้น) จะได้ 500,000 ส่วน 429,999 ปัดลงได้ 400,000 และ 551,000 ปัดขึ้นได้ 600,000'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/1] แบบรูปและความสัมพันธ์ของจำนวน', 'medium', 'mcq', 'จากแบบรูป 125, 250, 500, 1,000, ... จำนวนถัดไปคือจำนวนใด?', '["1,250","1,500","2,000","2,500"]'::jsonb, 2, 'เป็นแบบรูปที่มีความสัมพันธ์แบบเพิ่มขึ้นโดยการคูณด้วย 2 ทีละเท่าตัว ดังนั้น 1,000 x 2 = 2,000'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/2] การประมาณผลลัพธ์', 'hard', 'mcq', 'ผลบวกโดยประมาณของ 39,850 + 20,400 มีค่าใกล้เคียงข้อใดมากที่สุด?', '["50,000","60,000","70,000","80,000"]'::jsonb, 1, '39,850 ประมาณเป็น 40,000 และ 20,400 ประมาณเป็น 20,000 รวมกันได้ประมาณ 40,000 + 20,000 = 60,000'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/7] การบวกจำนวนนับที่มากกว่า 100,000', 'easy', 'mcq', 'ผลลัพธ์ของ 458,920 + 324,159 คือเท่าใด?', '["783,079","782,079","773,079","883,079"]'::jsonb, 0, '458,920 + 324,159 = 783,079'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/7] การลบจำนวนนับที่มากกว่า 100,000', 'easy', 'mcq', 'ผลลัพธ์ของ 800,000 - 347,650 มีค่าเท่าใด?', '["452,350","552,350","462,350","453,350"]'::jsonb, 0, '800,000 - 347,650 = 452,350'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/8] การคูณจำนวนที่มีหลายหลัก', 'medium', 'mcq', 'ผลคูณของ 1,245 x 36 มีค่าเท่ากับเท่าใด?', '["44,820","43,820","44,720","45,820"]'::jsonb, 0, '1,245 x 30 = 37,350 และ 1,245 x 6 = 7,470 นำมารวมกันได้ 37,350 + 7,470 = 44,820'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/8] การคูณจำนวนที่มีศูนย์ลงท้าย', 'easy', 'mcq', 'ผลคูณของ 700 x 500 เท่ากับเท่าใด?', '["3,500","35,000","350,000","3,500,000"]'::jsonb, 2, '7 x 5 = 35 เติมศูนย์ตามหลัง 4 ตัว (00 จาก 700 และ 00 จาก 500) ได้ 350,000'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/9] การหารที่ตัวหารมีสองหลัก', 'medium', 'mcq', 'ผลลัพธ์ของ 4,680 ÷ 15 คือข้อใด?', '["312","322","310","302"]'::jsonb, 0, '4,680 ÷ 15: 15 x 3 = 45 (เหลือเศษ 1 ดึง 8 เป็น 18), 15 x 1 = 15 (เหลือเศษ 3 ดึง 0 เป็น 30), 15 x 2 = 30 ลงตัว ได้ผลลัพธ์ 312'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/9] การหารมีเศษ', 'medium', 'mcq', '2,579 ÷ 8 ได้ผลหารและเศษตรงกับข้อใด?', '["322 เศษ 3","321 เศษ 5","322 เศษ 5","320 เศษ 7"]'::jsonb, 0, '322 x 8 = 2,576 และ 2,579 - 2,576 = 3 ดังนั้นได้ 322 เศษ 3'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/10] การบวก ลบ คูณ หารระคน', 'hard', 'mcq', 'หาผลลัพธ์ของ (450 + 150) x (200 - 160)', '["24,000","18,000","12,000","30,000"]'::jsonb, 0, 'คำนวณในวงเล็บก่อน: (450 + 150) = 600 และ (200 - 160) = 40 จากนั้นนำ 600 x 40 = 24,000'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/10] ลำดับการคำนวณ (Order of Operations)', 'hard', 'mcq', '100 + 50 x 2 - 40 มีค่าเท่ากับเท่าใด?', '["260","160","210","180"]'::jsonb, 1, 'ต้องทำคูณก่อน: 50 x 2 = 100 จากนั้นทำจากซ้ายไปขวา: 100 + 100 = 200 แล้ว 200 - 40 = 160'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/11] โจทย์ปัญหาการบวกและลบ', 'medium', 'mcq', 'โรงสีข้าวมีข้าวสาร 85,400 กิโลกรัม ขายไป 38,950 กิโลกรัม และซื้อเพิ่มอีก 15,000 กิโลกรัม ขณะนี้มีข้าวสารเหลือกี่กิโลกรัม?', '["61,450 กิโลกรัม","59,450 กิโลกรัม","62,550 กิโลกรัม","60,450 กิโลกรัม"]'::jsonb, 0, 'มีข้าวสาร 85,400 - 38,950 = 46,450 แล้วซื้อเพิ่ม 46,450 + 15,000 = 61,450 กิโลกรัม'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/11] โจทย์ปัญหาการคูณ', 'medium', 'mcq', 'โรงงานผลิตน้ำดื่มบรรจุลังละ 24 ขวด หากผลิตได้ 1,500 ลัง โรงงานมีน้ำดื่มทั้งหมดกี่ขวด?', '["36,000 ขวด","35,000 ขวด","38,000 ขวด","34,000 ขวด"]'::jsonb, 0, '1,500 x 24 = 36,000 ขวด'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/12] โจทย์ปัญหาการหาร', 'medium', 'mcq', 'คุณครูมีสมุด 1,200 เล่ม แจกให้นักเรียน 40 คน คนละเท่าๆ กัน นักเรียนจะได้รับคนละกี่เล่ม?', '["25 เล่ม","30 เล่ม","35 เล่ม","40 เล่ม"]'::jsonb, 1, '1,200 ÷ 40 = 30 เล่ม'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/12] โจทย์ปัญหาการบวก ลบ คูณ หารระคน 2 ขั้นตอน', 'hard', 'mcq', 'แม่ค้าซื้อส้ม 50 กิโลกรัม ราคากิโลกรัมละ 45 บาท นำไปขายกิโลกรัมละ 60 บาท หากขายหมดแม่ค้าจะได้กำไรกี่บาท?', '["650 บาท","750 บาท","800 บาท","950 บาท"]'::jsonb, 1, 'กำไรต่อกิโลกรัม = 60 - 45 = 15 บาท ขายได้ 50 กิโลกรัม ดังนั้นกำไรทั้งหมด = 50 x 15 = 750 บาท'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/12] โจทย์ปัญหาเกี่ยวกับเงิน', 'medium', 'mcq', 'ต้นกล้ามีเงิน 1,000 บาท ซื้อหนังสือ 2 เล่ม ราคาเล่มละ 230 บาท และซื้อกระเป๋า 350 บาท ต้นกล้าจะเหลือเงินกี่บาท?', '["190 บาท","210 บาท","240 บาท","180 บาท"]'::jsonb, 0, 'ค่าหนังสือ = 2 x 230 = 460 บาท รวมกับกระเป๋า = 460 + 350 = 810 บาท เงินที่เหลือ = 1,000 - 810 = 190 บาท'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/10] การหาค่าของตัวไม่ทราบค่าในประโยคสัญลักษณ์', 'hard', 'mcq', 'ถ้า ก x 25 = 1,500 แล้ว ก มีค่าเท่ากับเท่าใด?', '["50","60","70","80"]'::jsonb, 1, 'ก = 1,500 ÷ 25 = 60'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/3] เศษส่วนแท้ เศษเกิน และจำนวนคละ', 'easy', 'mcq', 'ข้อใดจัดเป็น "เศษเกิน"?', '["3/5","7/9","8/5","1/4"]'::jsonb, 2, 'เศษเกินคือเศษส่วนที่ตัวเศษมากกว่าหรือเท่ากับตัวส่วน ในที่นี้ 8/5 ตัวเศษ (8) มากกว่าตัวส่วน (5)'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/3] การเขียนเศษเกินในรูปจำนวนคละ', 'medium', 'mcq', '17/4 เขียนในรูปจำนวนคละได้ตรงกับข้อใด?', '["3 1/4","4 1/4","4 3/4","5 1/4"]'::jsonb, 1, '17 ÷ 4 ได้ 4 เศษ 1 ดังนั้น 17/4 = 4 1/4'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/3] การเขียนจำนวนคละในรูปเศษเกิน', 'medium', 'mcq', '3 2/5 เขียนเป็นเศษเกินได้เท่ากับข้อใด?', '["17/5","15/5","11/5","13/5"]'::jsonb, 0, '(3 x 5 + 2) / 5 = (15 + 2) / 5 = 17/5'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/4] เศษส่วนที่เท่ากัน', 'easy', 'mcq', 'เศษส่วนข้อใดมีค่าเท่ากับ 2/3?', '["4/9","6/9","8/15","4/5"]'::jsonb, 1, 'คูณทั้งตัวเศษและตัวส่วนด้วย 3: (2 x 3) / (3 x 3) = 6/9'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/4] การเปรียบเทียบเศษส่วน', 'medium', 'mcq', 'ข้อใดเปรียบเทียบเศษส่วนได้ถูกต้อง?', '["3/7 > 5/7","4/9 < 2/9","5/8 > 3/8","1/6 > 4/6"]'::jsonb, 2, 'เมื่อตัวส่วนเท่ากัน ให้ดูที่ตัวเศษ ซึ่ง 5 มากกว่า 3 ดังนั้น 5/8 > 3/8'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/4] การเปรียบเทียบเศษส่วนที่มีตัวส่วนไม่เท่ากัน', 'hard', 'mcq', 'เปรียบเทียบ 3/4 กับ 5/8 ข้อใดถูกต้อง?', '["3/4 > 5/8","3/4 < 5/8","3/4 = 5/8","เปรียบเทียบกันไม่ได้"]'::jsonb, 0, 'ทำตัวส่วนให้เท่ากัน: 3/4 = (3x2)/(4x2) = 6/8 ซึ่ง 6/8 > 5/8 ดังนั้น 3/4 > 5/8'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/13] การบวกเศษส่วนที่มีตัวส่วนเท่ากัน', 'easy', 'mcq', 'ผลบวกของ 3/11 + 5/11 เท่ากับเท่าใด?', '["8/22","8/11","15/11","2/11"]'::jsonb, 1, 'การบวกเศษส่วนที่ตัวส่วนเท่ากัน ให้นำตัวเศษบวกกัน ตัวส่วนคงเดิม: (3 + 5)/11 = 8/11'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/13] การลบเศษส่วนที่มีตัวส่วนเท่ากัน', 'easy', 'mcq', 'ผลลัพธ์ของ 9/12 - 4/12 คือข้อใด?', '["5/12","5/0","13/12","5/24"]'::jsonb, 0, '(9 - 4)/12 = 5/12'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/14] โจทย์ปัญหาการบวกเศษส่วน', 'medium', 'mcq', 'มานีอ่านหนังสือช่วงเช้าได้ 2/7 เล่ม ช่วงบ่ายอ่านได้อีก 3/7 เล่ม รวมทั้งวันมานีอ่านหนังสือได้คิดเป็นเศษส่วนเท่าใดของเล่ม?', '["5/14 เล่ม","5/7 เล่ม","6/7 เล่ม","1/7 เล่ม"]'::jsonb, 1, '2/7 + 3/7 = 5/7 เล่ม'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/14] โจทย์ปัญหาการลบเศษส่วน', 'medium', 'mcq', 'มีน้ำส้มอยู่ในเหยือก 7/8 ลิตร เทดื่มไป 3/8 ลิตร จะเหลือน้ำส้มในเหยือกกี่ลิตร?', '["4/8 ลิตร หรือ 1/2 ลิตร","10/8 ลิตร","4/16 ลิตร","1/8 ลิตร"]'::jsonb, 0, '7/8 - 3/8 = 4/8 ลิตร หรือทอนเป็นเศษส่วนอย่างต่ำได้ 1/2 ลิตร'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/5] การอ่านและการเขียนทศนิยม 1 ตำแหน่ง', 'easy', 'mcq', 'เศษส่วน 7/10 เขียนเป็นทศนิยมได้อย่างไร?', '["0.07","0.7","7.0","7.10"]'::jsonb, 1, 'ตัวส่วนเป็น 10 คือทศนิยม 1 ตำแหน่ง ดังนั้น 7/10 = 0.7'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/5] การอ่านและการเขียนทศนิยม 2 ตำแหน่ง', 'easy', 'mcq', '"สามจุดห้าสอง" เขียนเป็นตัวเลขทศนิยมได้อย่างไร?', '["3.52","3.25","3.502","35.2"]'::jsonb, 0, 'สามจุดห้าสอง เขียนเป็นตัวเลขอารบิกได้ 3.52'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/5] ค่าประจำหลักของทศนิยม', 'medium', 'mcq', 'ในทศนิยม 14.86 เลข 6 อยู่ในหลักใด และมีค่าเท่าใด?', '["หลักส่วนสิบ มีค่า 0.6","หลักส่วนร้อย มีค่า 0.06","หลักหน่วย มีค่า 6","หลักสิบ มีค่า 60"]'::jsonb, 1, 'หลังจุดตำแหน่งที่ 1 คือหลักส่วนสิบ (8 มีค่า 0.8), หลังจุดตำแหน่งที่ 2 คือหลักส่วนร้อย (6 มีค่า 0.06)'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/6] การเปรียบเทียบทศนิยม', 'medium', 'mcq', 'ข้อใดเปรียบเทียบทศนิยมได้ถูกต้อง?', '["0.4 > 0.45","1.25 < 1.3","3.08 > 3.8","5.6 = 5.06"]'::jsonb, 1, '1.25 เปรียบเทียบกับ 1.30: หลักส่วนสิบ 2 น้อยกว่า 3 ดังนั้น 1.25 < 1.3 ถูกต้อง'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/15] การบวกทศนิยมไม่เกินสองตำแหน่ง', 'easy', 'mcq', 'ผลบวกของ 12.35 + 4.8 เท่ากับเท่าใด?', '["17.15","16.43","17.35","16.15"]'::jsonb, 0, 'ตั้งจุดให้ตรงกัน: 12.35 + 4.80 = 17.15'),
('คณิตศาสตร์', 'ป.4', '[ค 1.1 ป.4/15] การลบทศนิยมไม่เกินสองตำแหน่ง', 'medium', 'mcq', '25.00 - 8.65 มีค่าเท่ากับข้อใด?', '["16.35","17.35","16.45","17.45"]'::jsonb, 0, '25.00 - 8.65 = 16.35'),
('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/1] การบอกระยะเวลาเป็นนาทีและชั่วโมง', 'easy', 'mcq', 'เวลา 180 นาที คิดเป็นกี่ชั่วโมง?', '["2 ชั่วโมง","3 ชั่วโมง","4 ชั่วโมง","5 ชั่วโมง"]'::jsonb, 1, '1 ชั่วโมง = 60 นาที ดังนั้น 180 ÷ 60 = 3 ชั่วโมง'),
('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/1] การเปลี่ยนหน่วยเวลา', 'medium', 'mcq', '3 สัปดาห์ 4 วัน รวมเป็นเวลากี่วัน?', '["21 วัน","24 วัน","25 วัน","28 วัน"]'::jsonb, 2, '1 สัปดาห์ = 7 วัน ดังนั้น 3 สัปดาห์ = 3 x 7 = 21 วัน บวกอีก 4 วัน = 25 วัน'),
('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/1] การหาเวลาสิ้นสุดกิจกรรม', 'medium', 'mcq', 'ภาพยนตร์เริ่มฉายเวลา 13.30 น. และฉายต่อเนื่องนาน 1 ชั่วโมง 45 นาที ภาพยนตร์จะฉายจบเวลาใด?', '["15.00 น.","15.15 น.","15.30 น.","14.45 น."]'::jsonb, 1, '13.30 น. + 1 ชั่วโมง = 14.30 น. บวกอีก 45 นาที = 15.15 น.'),
('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/1] การคำนวณระยะเวลาจากบันทึกกิจกรรม', 'hard', 'mcq', 'กานดานั่งรถไฟออกจากสถานีเวลา 08.45 น. ถึงปลายทางเวลา 14.20 น. กานดาใช้เวลาเดินทางนานเท่าใด?', '["5 ชั่วโมง 35 นาที","5 ชั่วโมง 45 นาที","6 ชั่วโมง 25 นาที","6 ชั่วโมง 35 นาที"]'::jsonb, 0, 'จาก 08.45 ถึง 13.45 = 5 ชั่วโมง และจาก 13.45 ถึง 14.20 = 35 นาที รวมเป็น 5 ชั่วโมง 35 นาที'),
('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/1] หน่วยเวลาปี เดือน สัปดาห์', 'easy', 'mcq', 'ระยะเวลา 2 ปี 6 เดือน คิดเป็นกี่เดือน?', '["24 เดือน","26 เดือน","30 เดือน","36 เดือน"]'::jsonb, 2, '1 ปี = 12 เดือน ดังนั้น 2 ปี = 24 เดือน บวกอีก 6 เดือน = 30 เดือน'),
('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/3] ความยาวรอบรูปของรูปสี่เหลี่ยมผืนผ้า', 'medium', 'mcq', 'รูปสี่เหลี่ยมผืนผ้ากว้าง 6 เซนติเมตร ยาว 10 เซนติเมตร จะมีความยาวรอบรูปกี่เซนติเมตร?', '["16 เซนติเมตร","32 เซนติเมตร","60 เซนติเมตร","48 เซนติเมตร"]'::jsonb, 1, 'ความยาวรอบรูปสี่เหลี่ยมผืนผ้า = 2 x (กว้าง + ยาว) = 2 x (6 + 10) = 2 x 16 = 32 เซนติเมตร'),
('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/3] ความยาวรอบรูปของรูปสี่เหลี่ยมจัตุรัส', 'easy', 'mcq', 'รูปสี่เหลี่ยมจัตุรัสมีด้านยาวด้านละ 8 เซนติเมตร มีความยาวรอบรูปเท่าใด?', '["16 เซนติเมตร","24 เซนติเมตร","32 เซนติเมตร","64 เซนติเมตร"]'::jsonb, 2, 'ความยาวรอบรูปสี่เหลี่ยมจัตุรัส = 4 x ความยาวด้าน = 4 x 8 = 32 เซนติเมตร'),
('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/3] พื้นที่ของรูปสี่เหลี่ยมมุมฉาก (สี่เหลี่ยมผืนผ้า)', 'medium', 'mcq', 'ห้องเรียนรูปสี่เหลี่ยมผืนผ้ากว้าง 7 เมตร ยาว 9 เมตร จะมีพื้นที่กี่ตารางเมตร?', '["32 ตารางเมตร","63 ตารางเมตร","16 ตารางเมตร","56 ตารางเมตร"]'::jsonb, 1, 'พื้นที่รูปสี่เหลี่ยมผืนผ้า = กว้าง x ยาว = 7 x 9 = 63 ตารางเมตร'),
('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/3] พื้นที่ของรูปสี่เหลี่ยมจัตุรัส', 'medium', 'mcq', 'กระดาษรูปสี่เหลี่ยมจัตุรัสยาวด้านละ 12 เซนติเมตร มีพื้นที่กี่ตารางเซนติเมตร?', '["48 ตารางเซนติเมตร","120 ตารางเซนติเมตร","144 ตารางเซนติเมตร","24 ตารางเซนติเมตร"]'::jsonb, 2, 'พื้นที่สี่เหลี่ยมจัตุรัส = ด้าน x ด้าน = 12 x 12 = 144 ตารางเซนติเมตร'),
('คณิตศาสตร์', 'ป.4', '[ค 2.1 ป.4/3] โจทย์ปัญหาพื้นที่และการปูพื้น', 'hard', 'mcq', 'สนามหญ้ารูปสี่เหลี่ยมผืนผ้ากว้าง 5 เมตร ยาว 8 เมตร ต้องการปูหญ้าให้เต็มสนามโดยหญ้าราคาตารางเมตรละ 60 บาท จะต้องจ่ายเงินค่าหญ้าทั้งหมดกี่บาท?', '["2,400 บาท","1,800 บาท","1,560 บาท","3,200 บาท"]'::jsonb, 0, 'พื้นที่สนาม = 5 x 8 = 40 ตารางเมตร ราคาหญ้าตารางเมตรละ 60 บาท ดังนั้นต้องจ่ายเงิน = 40 x 60 = 2,400 บาท'),
('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/1] จุด เส้นตรง รังสี และส่วนของเส้นตรง', 'easy', 'mcq', 'เส้นที่มีจุดปลายเพียงจุดเดียว เรียกว่าอะไร?', '["เส้นตรง","ส่วนของเส้นตรง","รังสี","เส้นขนาน"]'::jsonb, 2, 'รังสี คือเส้นที่มีจุดปลายเพียง 1 จุด และต่อออกไปในทิศทางเดียวได้ไม่สิ้นสุด'),
('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/1] ชนิดของมุม: มุมแหลม มุมฉาก มุมป้าน', 'easy', 'mcq', 'มุมที่มีขนาด 90 องศา เรียกว่ามุมอะไร?', '["มุมแหลม","มุมฉาก","มุมป้าน","มุมตรง"]'::jsonb, 1, 'มุมฉากมีขนาด 90 องศาพอดี (มุมแหลม < 90°, มุมป้าน 90° - 180°, มุมตรง = 180°)'),
('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/1] การเปรียบเทียบขนาดของมุม', 'medium', 'mcq', 'มุมที่มีขนาด 125 องศา จัดเป็นมุมชนิดใด?', '["มุมแหลม","มุมฉาก","มุมป้าน","มุมกลับ"]'::jsonb, 2, 'มุมที่มีขนาดมากกว่า 90 องศาแต่น้อยกว่า 180 องศา เรียกว่า "มุมป้าน"'),
('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/2] สมบัติของรูปสี่เหลี่ยมจัตุรัส', 'easy', 'mcq', 'ข้อใดเป็นสมบัติเด่นของ "รูปสี่เหลี่ยมจัตุรัส"?', '["ด้านทั้งสี่ยาวเท่ากัน และมุมทุกมุมเป็นมุมฉาก","ด้านตรงข้ามยาวเท่ากัน และมุมทุกมุมเป็นมุมแหลม","มีด้านขนานกันเพียงคู่เดียว","มุมทุกมุมมีขนาด 60 องศา"]'::jsonb, 0, 'รูปสี่เหลี่ยมจัตุรัสมีด้านทั้งสี่ยาวเท่ากันทุกด้าน และมุมภายในทุกมุมเป็นมุมฉาก (90 องศา)'),
('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/2] สมบัติของรูปสี่เหลี่ยมผืนผ้า', 'easy', 'mcq', 'รูปสี่เหลี่ยมที่มีมุมทุกมุมเป็นมุมฉาก และด้านตรงข้ามยาวเท่ากันแต่ด้านติดกันยาวไม่เท่ากัน คือรูปสี่เหลี่ยมใด?', '["สี่เหลี่ยมขนมเปียกปูน","สี่เหลี่ยมผืนผ้า","สี่เหลี่ยมคางหมู","สี่เหลี่ยมรูปว่าว"]'::jsonb, 1, 'รูปสี่เหลี่ยมผืนผ้ามีมุมทุกมุมเป็นมุมฉาก ด้านตรงข้ามยาวเท่ากันและขนานกัน'),
('คณิตศาสตร์', 'ป.4', '[ค 2.2 ป.4/2] แกนสมมาตร', 'medium', 'mcq', 'รูปสี่เหลี่ยมจัตุรัสมีแกนสมมาตรทั้งหมดกี่แกน?', '["2 แกน","3 แกน","4 แกน","8 แกน"]'::jsonb, 2, 'สี่เหลี่ยมจัตุรัสมีแกนสมมาตร 4 แกน (แนวนอน, แนวตั้ง, และเส้นทแยงมุม 2 เส้น)'),
('คณิตศาสตร์', 'ป.4', '[ค 3.1 ป.4/1] การอ่านแผนภูมิแท่ง', 'easy', 'mcq', 'จากแผนภูมิแท่งแสดงจำนวนนักเรียนที่ชอบกีฬาต่างๆ: ฟุตบอล 18 คน, ว่ายน้ำ 12 คน, แบดมินตัน 15 คน กีฬาชนิดใดมีนักเรียนชอบมากที่สุด และชอบมากกว่าว่ายน้ำกี่คน?', '["ฟุตบอล มากกว่า 6 คน","แบดมินตัน มากกว่า 3 คน","ฟุตบอล มากกว่า 3 คน","ว่ายน้ำ มากกว่า 6 คน"]'::jsonb, 0, 'ฟุตบอลมีผู้ชอบมากที่สุด 18 คน และมากกว่าว่ายน้ำ (12 คน) อยู่ 18 - 12 = 6 คน'),
('คณิตศาสตร์', 'ป.4', '[ค 3.1 ป.4/1] การแปลความหมายแผนภูมิแท่งย่นระยะ', 'medium', 'mcq', 'เส้นหยักบนแกนแสดงจำนวนในแผนภูมิแท่ง มีจุดประสงค์เพื่ออะไร?', '["ตกแต่งให้สวยงาม","ละการแสดงข้อมูลในช่วงที่มีค่าน้อยหรือไม่มีข้อมูล เพื่อประหยัดเนื้อที่","แสดงว่าข้อมูลเกิดข้อผิดพลาด","แสดงข้อมูลที่เพิ่มขึ้นอย่างรวดเร็ว"]'::jsonb, 1, 'การย่นระยะของเส้นแสดงจำนวน ใช้เพื่อละข้อมูลในช่วงเริ่มต้นที่ไม่มีข้อมูล ทำให้แสดงความต่างของข้อมูลได้ชัดเจนขึ้น'),
('คณิตศาสตร์', 'ป.4', '[ค 3.1 ป.4/1] การอ่านข้อมูลจากตารางสองทาง (Two-way Table)', 'medium', 'mcq', 'ในตารางแสดงจำนวนนักเรียนชาย-หญิง ป.4: ชายชอบคณิตศาสตร์ 14 คน หญิงชอบคณิตศาสตร์ 16 คน, ชายชอบวิทยาศาสตร์ 12 คน หญิงชอบวิทยาศาสตร์ 15 คน มีนักเรียนชอบวิชาคณิตศาสตร์รวมทั้งหมดกี่คน?', '["26 คน","30 คน","27 คน","57 คน"]'::jsonb, 1, 'นักเรียนที่ชอบคณิตศาสตร์รวม = ชาย 14 + หญิง 16 = 30 คน'),
('คณิตศาสตร์', 'ป.4', '[ค 3.1 ป.4/1] การใช้ข้อมูลจากตารางสองทางแก้ปัญหา', 'hard', 'mcq', 'จากข้อมูลตารางสองทาง หากมีนักเรียนชั้น ป.4 ทั้งหมด 60 คน เป็นนักเรียนชาย 28 คน และมีนักเรียนหญิงที่มาโรงเรียนด้วยรถโดยสาร 18 คน ถ้ามีนักเรียนหญิงทั้งหมดกี่คน?', '["28 คน","30 คน","32 คน","34 คน"]'::jsonb, 2, 'นักเรียนทั้งหมด 60 คน เป็นชาย 28 คน ดังนั้นเป็นนักเรียนหญิง = 60 - 28 = 32 คน');
INSERT INTO public.exam_sets (title, subject, grade, questions, time_limit_minutes, pass_threshold_pct, pin_code, is_active)
